/bin/zsh -c "python3 -c 'import pandas as pd,json; from pathlib import Path; p=Path(\"evidence/source_room\");
for fn in [\"orders-part1.csv\",\"orders-part2.csv\",\"order-corrections.csv\",\"returns.csv\",\"ecb-history.csv\",\"hub-options.csv\",\"unit-costs.csv\"]:
 df=pd.read_csv(p/fn); print(\"\\\\n\",fn,df.shape,list(df.columns)); print(df.head(2).to_dict(\"records\"));
 if \"order_id\" in df: print(\"order_id dup\",df[\"order_id\"].duplicated(keep=False).sum(),\"unique\",df[\"order_id\"].nunique(),\"revisions\",df[\"revision\"].value_counts().to_dict())
 if \"return_id\" in df: print(\"return_id dup\",df[\"return_id\"].duplicated(keep=False).sum(),\"unique\",df[\"return_id\"].nunique(),\"revisions\",df[\"revision\"].value_counts().to_dict())
 for c in [\"country\",\"status\",\"is_test\",\"currency\",\"sku\"]:
  if c in df: print(c,df[c].value_counts(dropna=False).to_dict())
 for c in [\"shipped_at\",\"ordered_at\",\"received_at\",\"valid_from\",\"Date\"]:
  if c in df: print(c,pd.to_datetime(df[c],errors=\"coerce\").min(),pd.to_datetime(df[c],errors=\"coerce\").max())
for fn in [\"population.json\",\"gdp-per-capita.json\"]:
 x=json.load(open(p/fn)); print(fn,\"metadata\",x[0]); rows=x[1]; print(\"rows\",len(rows),\"missing\",sum(r[\"value\"] is None for r in rows))'"

